package ru.voboost.voyemu;

import static org.junit.jupiter.api.Assertions.*;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import ru.voboost.tests.logging.InstallerLogs;

class SettingsDialogMeasurementsTest {
    static final String ROOT="com.android.internal.policy.DecorView@d00d",BUTTON="android.widget.Button";
    static JsonObject o(Object...p){return SettingsOemMeasurementsTest.object(p);}
    static JsonObject node(String identity,String parent,String kind,JsonObject bounds){return o("id","dialog:"+identity,"parent",parent,"window_id","dialog","class",kind,"package",SystemLanguagePicker.OWNER,"present",true,"visible",true,"bridge_version",1,"bounds",bounds,"clipped_bounds",bounds.deepCopy());}
    static JsonObject ui(){var ui=SettingsOemMeasurementsTest.observation();var s=ui.getAsJsonArray("screens").get(0).getAsJsonObject();JsonArray nodes=s.getAsJsonArray("nodes"),windows=s.getAsJsonArray("windows");nodes.add(node(ROOT,"","com.android.internal.policy.DecorView",o("x",300,"y",100,"width",1000,"height",500)));for(int i=0;i<2;i++){int x=i==0?420:950;var b=node(BUTTON+"@"+(i==0?"aa11":"bb22"),"dialog:"+ROOT,BUTTON,o("x",x,"y",430,"width",200,"height",70));b.add("layout",o("measured_width",200,"measured_height",70));b.add("text_style",o("text_size_px",28));b.addProperty("text",i==0?"Remove":"Cancel");nodes.add(b);}windows.add(o("id","dialog","type",2,"package",SystemLanguagePicker.OWNER,"read_complete",true,"root_id","dialog:"+ROOT,"node_count",3));return ui;}
    static List<InstallerLogs.Diagnostic> rows(){var rs=new ArrayList<InstallerLogs.Diagnostic>();var h=SettingsOemMeasurementsTest.rows().get(0).fields().deepCopy();h.addProperty("surface","dialog");h.addProperty("phase","pre-click");h.addProperty("count",2);h.addProperty("sections",0);h.addProperty("rootWidth",1000);rs.add(SettingsOemMeasurementsTest.diag(3,"ui.layout.capture",h));for(int i=0;i<2;i++){String role="dialog."+(i==0?"confirm":"cancel"),value=i==0?"confirm":"cancel";int x=i==0?420:950;rs.add(SettingsOemMeasurementsTest.diag(4+i*3,"ui.layout.identity",o("captureId","capture","role",role,"value",value,"viewIdentity",BUTTON+"@"+(i==0?"aa11":"bb22"),"rootIdentity",ROOT,"screenX",x,"screenY",430)));rs.add(SettingsOemMeasurementsTest.diag(5+i*3,"ui.layout",o("captureId","capture","role",role,"value",value,"width",200,"min_width",0,"padding_left",38,"padding_right",38,"caption_px",60,"top",330,"bottom",400,"lines",1,"ellipsis",0)));rs.add(SettingsOemMeasurementsTest.diag(6+i*3,"ui.layout.geometry",o("captureId","capture","role",role,"value",value,"height",70,"left",x-300,"right",x-100,"parentWidth",1000,"class",BUTTON,"textSize",28,"paddingTop",0,"paddingBottom",0,"layoutWidth",124)));}rs.add(SettingsOemMeasurementsTest.diag(10,"ui.layout.root",o("captureId","capture","rootIdentity",ROOT,"screenX",300,"screenY",100)));return rs;}
    static JsonObject read(List<InstallerLogs.Diagnostic> rows,JsonObject ui)throws Exception{return SettingsOemMeasurements.readDialog(SettingsOemMeasurementsTest.baseline(),SettingsOemMeasurementsTest.snapshot(rows,List.of(new InstallerLogs.DaemonEvent(BigInteger.TWO,"runtime","desired-snapshot-queued",SettingsOemMeasurementsTest.queue()))),SettingsOemMeasurementsTest.runtime(),ui,"profile","session",SettingsOemMeasurementsTest.BOOT,"en");}
    @Test void currentDialogHasIndependentActualRootWindowAndBothSourceBoundActions()throws Exception{var r=read(rows(),ui());assertEquals("dialog",r.get("surface").getAsString());assertEquals("dialog",r.get("windowId").getAsString());assertTrue(r.get("sourceRootObserved").getAsBoolean());assertEquals(2,r.getAsJsonArray("rows").size());assertEquals("42",r.get("targetPid").getAsString());assertFalse(r.get("visualAcceptance").getAsBoolean());}
    @Test void panelProofCannotBeUsedAsDialogOrItsClassNameBorrowedAsWindowAuthority()throws Exception{assertThrows(IOException.class,()->read(SettingsOemMeasurementsTest.rows(),SettingsOemMeasurementsTest.observation()));var rs=rows();rs.get(1).fields().addProperty("rootIdentity","android.widget.LinearLayout@2222");assertThrows(IOException.class,()->read(rs,ui()));var tree=ui();tree.getAsJsonArray("screens").get(0).getAsJsonObject().getAsJsonArray("windows").get(1).getAsJsonObject().addProperty("type",1);assertThrows(IOException.class,()->read(rows(),tree));}
    @Test void duplicateRootHashForeignOwnerAndIncompleteDialogAreRejected()throws Exception{for(String mutation:List.of("collision","foreign","incomplete","missingCancel")){var tree=ui();var s=tree.getAsJsonArray("screens").get(0).getAsJsonObject();switch(mutation){case"collision"->{var copy=s.getAsJsonArray("nodes").get(3).getAsJsonObject().deepCopy();copy.addProperty("id","foreign:"+ROOT);copy.addProperty("window_id","foreign");s.getAsJsonArray("nodes").add(copy);}case"foreign"->s.getAsJsonArray("windows").get(1).getAsJsonObject().addProperty("package","foreign.app");case"incomplete"->s.getAsJsonArray("windows").get(1).getAsJsonObject().addProperty("read_complete",false);case"missingCancel"->s.getAsJsonArray("nodes").remove(5);}assertThrows(IOException.class,()->read(rows(),tree),mutation);}}
    @Test void scopedAncestorScrollPreservesTheSameViewButRelativeMotionDoesNot()throws Exception{var rs=SettingsOemMeasurementsTest.rows();rs.add(SettingsOemMeasurementsTest.diag(7,"ui.layout.root",o("captureId","capture","rootIdentity","android.widget.LinearLayout@2222","screenX",485,"screenY",50)));var tree=SettingsOemMeasurementsTest.observation();var nodes=tree.getAsJsonArray("screens").get(0).getAsJsonObject().getAsJsonArray("nodes");nodes.get(1).getAsJsonObject().add("bounds",o("x",485,"y",-250,"width",1364,"height",1000));nodes.get(2).getAsJsonObject().getAsJsonObject("bounds").addProperty("y",-200);var result=SettingsOemMeasurementsTest.read(rs,SettingsOemMeasurementsTest.queue(),tree);assertTrue(result.get("sourceRootObserved").getAsBoolean());nodes.get(2).getAsJsonObject().getAsJsonObject("bounds").addProperty("y",-199);assertThrows(IOException.class,()->SettingsOemMeasurementsTest.read(rs,SettingsOemMeasurementsTest.queue(),tree));}
    @Test void wrongCurrentEndpointRootMetricOrDuplicatedActionCannotBorrowTheDialogCapture()throws Exception{for(String mutation:List.of("epoch","root","duplicate")){var rs=rows();switch(mutation){case"epoch"->rs.get(1).sourceFields().addProperty("endpointEpoch","6");case"root"->rs.get(7).fields().addProperty("screenY",101);case"duplicate"->rs.add(SettingsOemMeasurementsTest.diag(11,"ui.layout",rs.get(2).fields().deepCopy()));}assertThrows(IOException.class,()->read(rs,ui()),mutation);}}
    static JsonObject withMessage() {
        JsonObject tree=ui(),surface=tree.getAsJsonArray("screens").get(0).getAsJsonObject();
        JsonObject message=node("android.widget.TextView@cc33","dialog:"+ROOT,"android.widget.TextView",o("x",500,"y",200,"width",250,"height",70));
        JsonObject actual=SettingsTextLayoutTest.target("Message");message.addProperty("text","Message");message.add("layout",actual.get("layout"));message.add("text_style",actual.get("textStyle"));message.add("text_layout",actual.get("textLayout"));surface.getAsJsonArray("nodes").add(message);surface.getAsJsonArray("windows").get(1).getAsJsonObject().addProperty("node_count",4);return tree;
    }
    @Test void actualDialogMessageIsBoundToSameObservedWindowAndNativeLayout()throws Exception {
        JsonObject tree=withMessage(),measured=read(rows(),tree);JsonObject result=SettingsOemMeasurements.dialogMessage(measured,tree,"Message");
        assertEquals(3,result.getAsJsonArray("rows").size());var message=result.getAsJsonArray("rows").get(2).getAsJsonObject();assertEquals("dialog.message",message.get("role").getAsString());assertTrue(message.has("textLayout"));assertEquals("dialog:android.widget.TextView@cc33",message.get("nodeId").getAsString());
    }
    @Test void staleDialogWrongCaptionDuplicateMessageOrMissingNativeLayoutCannotUseAnotherWindow()throws Exception {
        for(String mutation:List.of("stale","caption","duplicate","layout","foreign")) {
            JsonObject tree=withMessage(),measured=read(rows(),tree);var surface=tree.getAsJsonArray("screens").get(0).getAsJsonObject();var node=surface.getAsJsonArray("nodes").get(6).getAsJsonObject();
            switch(mutation){case"stale"->tree.addProperty("observation_id","other");case"caption"->node.addProperty("text","Other");case"layout"->node.remove("text_layout");
                case"duplicate"->{var copy=node.deepCopy();copy.addProperty("id","dialog:android.widget.TextView@dd44");surface.getAsJsonArray("nodes").add(copy);surface.getAsJsonArray("windows").get(1).getAsJsonObject().addProperty("node_count",5);}
                case"foreign"->{node.addProperty("id","w:android.widget.TextView@cc33");node.addProperty("window_id","w");node.addProperty("parent","w:android.widget.LinearLayout@2222");surface.getAsJsonArray("windows").get(0).getAsJsonObject().addProperty("node_count",4);surface.getAsJsonArray("windows").get(1).getAsJsonObject().addProperty("node_count",3);}}
            assertThrows(IOException.class,()->SettingsOemMeasurements.dialogMessage(measured,tree,"Message"),mutation);
        }
    }

}
